M.profiles=profiles
local checked=setmetatable({},{__mode='k'})
function M.prepare(mesh)
 if checked[mesh]~=nil then return checked[mesh]or nil end
 local ok,n=pcall(mesh.getVertexCount,mesh)
 local p=ok and profiles[n]
 if not p or type(mesh.getVertexAttribute)~='function' or type(mesh.setVertexAttribute)~='function'then
  checked[mesh]=false;return nil
 end
 -- Vertex count alone is not identity. Verify every eye UV before using
 -- this layout, including animated meshes with the same neutral UVs.
 for _,r in ipairs(p.uv)do
  local good,u,v=pcall(mesh.getVertexAttribute,mesh,r[1],2)
  if not good or type(u)~='number'or type(v)~='number'
   or math.abs(u-r[2])>.00002 or math.abs(v-r[3])>.00002 then
   checked[mesh]=false;return nil
  end
 end
 checked[mesh]=p
 return p
end
function M.draw(draw,mesh,tex,model,pull,sun,ranges,closure)
 if not mesh or (closure or 0)<.20 then return draw(mesh,tex,model,pull,sun,ranges)end
 if (closure or 0)>=.65 and V and V.require then
  local ok,P=pcall(V.require,'ParadePlayerSleepEyes')
  if ok and P then tex=P.texture(mesh,tex)end
 end
 local p=M.prepare(mesh)
 if not p then return draw(mesh,tex,model,pull,sun,ranges)end
 local du,dv=0,0
 if p.shut then
  local o=closure<.65 and(p.half or p.shut)or p.shut
  du,dv=o[1],o[2]
 else dv=p.step*(closure<.65 and 1 or 2)end
 local changed=0
 local ok=pcall(function()
  for i,r in ipairs(p.uv)do
   changed=i
   mesh:setVertexAttribute(r[1],2,r[2]+du,r[3]+dv)
  end
 end)
 -- A failed UV upload falls back to the untouched model, not a missing NPC.
 if not ok then
  for i=1,changed do local r=p.uv[i];pcall(mesh.setVertexAttribute,mesh,r[1],2,r[2],r[3])end
  checked[mesh]=false
  return draw(mesh,tex,model,pull,sun,ranges)
 end
 local good,result=pcall(draw,mesh,tex,model,pull,sun,ranges)
 local restoreError
 for i=1,changed do
  local r=p.uv[i]
  local restored,err=pcall(mesh.setVertexAttribute,mesh,r[1],2,r[2],r[3])
  if not restored then restoreError=err end
 end
 if restoreError then checked[mesh]=false;error(restoreError,0)end
 if not good then error(result,0)end
 return result
end
function M.clear()
 checked=setmetatable({},{__mode='k'})
 if V and V.require then
  local ok,P=pcall(V.require,'ParadePlayerSleepEyes');if ok and P then P.clear()end
 end
end
return M
